import{_ as t,o as r,c as n,a2 as a}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Zähler-Reset und Überlauf","description":"","frontmatter":{"order":2,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/05.hintergrund/02.zaehler-reset.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/hintergrund/zaehler-reset.md","filePath":"de/adapter/sourceanalytix/hintergrund/zaehler-reset.md","lastUpdated":null}'),i={name:"de/adapter/sourceanalytix/hintergrund/zaehler-reset.md"};function s(d,e,l,u,h,o){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="zahler-reset-und-uberlauf" tabindex="-1">Zähler-Reset und Überlauf <a class="header-anchor" href="#zahler-reset-und-uberlauf" aria-label="Permalink to &quot;Zähler-Reset und Überlauf&quot;">​</a></h1><p><a id="device-reset-detected-mean-reset"></a></p><h2 id="was-bedeutet-device-reset-detected-und-wie-funktioniert-die-reset-erkennung" tabindex="-1">Was bedeutet &quot;Device reset detected&quot; und wie funktioniert die Reset-Erkennung? <a class="header-anchor" href="#was-bedeutet-device-reset-detected-und-wie-funktioniert-die-reset-erkennung" aria-label="Permalink to &quot;Was bedeutet &quot;Device reset detected&quot; und wie funktioniert die Reset-Erkennung?&quot;">​</a></h2><p><strong>Kurz:</strong> „Device reset detected&quot; ist eine Warnung, kein Fehler. SourceAnalytix hat bemerkt, dass der Zählerstand deiner Quelle deutlich gefallen ist (Neustart, Stromausfall, Überlauf oder Zählertausch), und zählt ab jetzt auf den bisherigen Gesamtstand weiter. Es geht kein Verbrauch verloren und es entstehen keine negativen Werte.</p><h3 id="die-begriffe" tabindex="-1">Die Begriffe <a class="header-anchor" href="#die-begriffe" aria-label="Permalink to &quot;Die Begriffe&quot;">​</a></h3><p>Diese Begriffe gelten in der ganzen Doku.</p><table tabindex="0"><thead><tr><th>Begriff</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Zieleinheit</td><td>Die Einheit der Preisdefinition, die du der Quelle zugeordnet hast, z. B. kWh. In ihr rechnet SourceAnalytix alles: Gesamtstand, Startwerte und Schwelle.</td></tr><tr><td>Gerätewert</td><td>Der Wert deines Quell-Datenpunkts, umgerechnet in die Zieleinheit. Er kann zurückfallen, z. B. nach einem Neustart des Geräts.</td></tr><tr><td>Gesamtstand</td><td>Der eigene Zählerstand von SourceAnalytix im State <code>sourceanalytix.0.&lt;Gerät&gt;.cumulativeReading</code>. Er fällt bei eingeschalteter Reset-Erkennung nie von selbst.</td></tr><tr><td>Offset</td><td>Der Wert <code>valueAtDeviceReset</code> in den SourceAnalytix-Einstellungen der Quelle. Es gilt: Gesamtstand = Gerätewert + Offset. Ohne Reset ist er 0. Bis v0.6.x zeigt ihn kein Dialog an, ab v0.7.0 steht er bei der Quelle unter „Für Experten&quot;.</td></tr><tr><td>Startwert</td><td>Der Gesamtstand zu Beginn einer Periode („Tag&quot;, „Woche&quot;, „Monat&quot;, „Quartal&quot;, „Jahr&quot;). Verbrauch der Periode = Gesamtstand − Startwert.</td></tr><tr><td>Schwelle</td><td>Das Feld „Schwelle&quot; in den Einstellungen der Quelle. Der größte Rückgang, der noch als Messschwankung gilt. In der Zieleinheit, Standard 1.</td></tr><tr><td>Reset</td><td>Der Gerätewert fällt um mehr als die Schwelle. Ursache kann ein Neustart, ein Überlauf oder ein neuer Zähler sein.</td></tr></tbody></table><h3 id="so-lauft-die-erkennung-ab" tabindex="-1">So läuft die Erkennung ab <a class="header-anchor" href="#so-lauft-die-erkennung-ab" aria-label="Permalink to &quot;So läuft die Erkennung ab&quot;">​</a></h3><p>Mit jedem neuen Gerätewert rechnet SourceAnalytix Gerätewert + Offset und vergleicht das Ergebnis mit dem letzten Gesamtstand:</p><ol><li><strong>Gleich oder höher:</strong> Der Wert wird übernommen.</li><li><strong>Niedriger, aber höchstens um die Schwelle:</strong> Das gilt als Messschwankung. Der Gesamtstand bleibt stehen, der Wert wird ignoriert.</li><li><strong>Niedriger um mehr als die Schwelle:</strong> Das ist ein möglicher Reset. SourceAnalytix behält den Gesamtstand, schreibt „Waiting for another reading before confirming a possible device reset&quot; ins Log und wartet auf den nächsten Wert.</li><li><strong>Der nächste Wert entscheidet:</strong><ul><li>Liegt er wieder nahe am alten Wert (innerhalb der Schwelle) oder ist er mehr als die Hälfte des Weges zurückgestiegen, war der niedrige Wert ein Ausreißer. Er wird verworfen, im Log steht „Rejected a possible device reset&quot;.</li><li>Liegt er gleich hoch oder höher als der niedrige Wert, aber noch unten, ist der Reset bestätigt. SourceAnalytix setzt den Offset auf alten Gesamtstand − niedrigen Gerätewert und meldet „Device reset detected for … preserving cumulative value … with new offset …&quot;. Ab jetzt zählt der Gerätewert auf den alten Gesamtstand weiter.</li><li>Liegt er noch tiefer, wartet SourceAnalytix weiter.</li></ul></li></ol><p>Ein Beispiel mit Schwelle 1 kWh: Der Zähler steht bei 1.000 kWh und startet nach einem Stromausfall bei 0.</p><table tabindex="0"><thead><tr><th>Gerätewert</th><th>Offset</th><th>Gesamtstand</th><th>Log</th></tr></thead><tbody><tr><td>1.000 kWh</td><td>0</td><td>1.000 kWh</td><td>–</td></tr><tr><td>0 kWh</td><td>0</td><td>1.000 kWh</td><td>„Waiting for another reading …&quot;</td></tr><tr><td>0,4 kWh</td><td>1.000</td><td>1.000,4 kWh</td><td>„Device reset detected …&quot;</td></tr><tr><td>1,0 kWh</td><td>1.000</td><td>1.001 kWh</td><td>–</td></tr></tbody></table><p>Verloren geht nur, was das Gerät zwischen seinem letzten Wert vor dem Reset und dem ersten Wert danach gezählt hat, denn diesen Teil hat das Gerät selbst nicht mehr gemeldet.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Steigt der erste Wert nach einem echten Reset schon mehr als die Hälfte des Weges zurück, hält SourceAnalytix ihn für einen Ausreißer. Der Verbrauch seit dem Reset wird dann nicht gezählt, und das Log sagt das mit „Rejected a possible device reset … If the device was really reset, consumption since the reset was not counted&quot;. Korrigieren kannst du das wie unter <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a> beschrieben.</p></div><h3 id="uberlauf-stromausfall-und-neustart-von-sourceanalytix" tabindex="-1">Überlauf, Stromausfall und Neustart von SourceAnalytix <a class="header-anchor" href="#uberlauf-stromausfall-und-neustart-von-sourceanalytix" aria-label="Permalink to &quot;Überlauf, Stromausfall und Neustart von SourceAnalytix&quot;">​</a></h3><ul><li><strong>Überlauf:</strong> Ein Zähler, der nach seinem Höchstwert wieder bei 0 beginnt, ist für SourceAnalytix ein gewöhnlicher Reset.</li><li><strong>Stromausfall am Gerät:</strong> Startet das Gerät bei 0 oder einem kleineren Wert, ist das ebenfalls ein Reset.</li><li><strong>SourceAnalytix war gestoppt:</strong> Der Gesamtstand ist im State <code>cumulativeReading</code> gespeichert. Ein Reset, der in dieser Zeit passiert ist, wird beim ersten Wert nach dem Start erkannt, solange Gerätewert + Offset dann noch um mehr als die Schwelle unter dem gespeicherten Gesamtstand liegt.</li><li><strong>Leistungsquellen (W):</strong> Für sie gibt es keine Reset-Erkennung. Sie liefern keinen Zählerstand, den SourceAnalytix vergleichen könnte.</li></ul><h3 id="wenn-die-reset-erkennung-aus-ist" tabindex="-1">Wenn die Reset-Erkennung aus ist <a class="header-anchor" href="#wenn-die-reset-erkennung-aus-ist" aria-label="Permalink to &quot;Wenn die Reset-Erkennung aus ist&quot;">​</a></h3><p>Ohne das Häkchen „Erkennung der Zurücksetzung des Gerätewerts Aktiviert&quot; übernimmt SourceAnalytix jeden Rückgang. Gesamtstand und Periodenwerte fallen dann mit, und der Verbrauch kann negativ werden. Das ist nur für Quellen gedacht, die bewusst fallen dürfen. Im Log steht bei jedem Rückgang „Cumulative reading for … decreased while reset detection is disabled&quot;.</p><p><strong>Bis v0.6.1:</strong> Diese Meldung steht auf Stufe Info und kann bei fallenden Quellen das Log füllen. <strong>Ab v0.6.2</strong> steht sie nur noch im Debug-Log (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1262" target="_blank" rel="noreferrer">#1262</a>).</p><p>Die ältere Meldung „Device reset detected … feature disabled (or below threshold)&quot; gibt es nur bis v0.4.x. Seit v0.5.0 ist sie durch die Meldungen oben ersetzt. Siehst du sie noch, aktualisiere SourceAnalytix.</p><h3 id="was-sich-ab-v0-6-2-andert" tabindex="-1">Was sich ab v0.6.2 ändert <a class="header-anchor" href="#was-sich-ab-v0-6-2-andert" aria-label="Permalink to &quot;Was sich ab v0.6.2 ändert&quot;">​</a></h3><p><strong>Ab v0.6.2:</strong> Ein bestätigter Reset wird zurückgenommen, wenn der alte Gerätewert in einem Schritt zurückkommt. Beispiel: Ein Gerät meldet 1.000, dann zweimal 0, dann wieder 1.000. Bis v0.6.1 verdoppelte sich dabei der Gesamtstand auf 2.000. Ab v0.6.2 stellt SourceAnalytix den alten Offset wieder her, der Gesamtstand bleibt bei 1.000, und im Log steht „Rolled back the device reset of …&quot; (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1258" target="_blank" rel="noreferrer">#1258</a>).</p><p><strong>Ab v0.6.2:</strong> Ist der Offset größer als der Gesamtstand (meist nach einer Korrektur von Hand oder einem Zählertausch), läuft die Quelle weiter. SourceAnalytix warnt „Known valueAtDeviceReset … is larger than the known cumulative value …&quot; und setzt den Offset beim nächsten Wert auf Gesamtstand − Gerätewert. Bis v0.6.1 stoppte die Quelle stattdessen mit dem Fehler „Check settings for … Known valueAtDeviceReset … &gt; known cumulative value … cannot proceed&quot; (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1257" target="_blank" rel="noreferrer">#1257</a>).</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#threshold-disabling-reset-detection-work">Schwelle und Abschalten der Reset-Erkennung</a> · <a href="./../anleitungen/zaehlerstaende-korrigieren#meter-restarts-after-power-loss">Zähler startet nach Stromausfall bei 0</a> · <a href="./../fehlerbehebung/log-meldungen#error-known-valueatdevicereset-known-cumulative">Fehler „Known valueAtDeviceReset &gt; known cumulative value&quot;</a></p><p><a id="counter-reset-0-daily-happens"></a></p><h2 id="zahler-der-taglich-auf-0-zuruckgesetzt-wird-–-was-passiert-intern" tabindex="-1">Zähler, der täglich auf 0 zurückgesetzt wird – was passiert intern? <a class="header-anchor" href="#zahler-der-taglich-auf-0-zuruckgesetzt-wird-–-was-passiert-intern" aria-label="Permalink to &quot;Zähler, der täglich auf 0 zurückgesetzt wird – was passiert intern?&quot;">​</a></h2><p><strong>Kurz:</strong> Mit eingeschalteter Reset-Erkennung behandelt SourceAnalytix den nächtlichen Sprung auf 0 wie jeden anderen Reset: Es wartet auf den nächsten Wert, setzt dann den Offset und zählt den Gesamtstand weiter. Pro Nacht fehlt nur ein kleiner Rest. Ist die Reset-Erkennung aus, übernimmt SourceAnalytix den Rückgang, und der Verbrauch des Vortags wird am nächsten Tag wieder abgezogen.</p><h3 id="was-in-der-nacht-passiert" tabindex="-1">Was in der Nacht passiert <a class="header-anchor" href="#was-in-der-nacht-passiert" aria-label="Permalink to &quot;Was in der Nacht passiert&quot;">​</a></h3><p>Ein Beispiel mit Schwelle 0,1 kWh. Der Tageszähler stand am Abend bei 4,2 kWh, aus früheren Nächten ist der Offset 1.000 kWh.</p><table tabindex="0"><thead><tr><th>Zeit</th><th>Gerätewert</th><th>Offset</th><th>Gesamtstand</th><th>Was passiert</th></tr></thead><tbody><tr><td>23:58</td><td>4,2 kWh</td><td>1.000</td><td>1.004,2 kWh</td><td>–</td></tr><tr><td>0:00</td><td>–</td><td>1.000</td><td>1.004,2 kWh</td><td>Periodenwechsel: Startwert „Tag&quot; wird 1.004,2 kWh</td></tr><tr><td>0:01</td><td>0 kWh</td><td>1.000</td><td>1.004,2 kWh</td><td>Log „Waiting for another reading …&quot;</td></tr><tr><td>0:10</td><td>0,05 kWh</td><td>1.004,2</td><td>1.004,25 kWh</td><td>Log „Device reset detected …&quot;, heute 0,05 kWh</td></tr></tbody></table><p>Der Periodenwechsel um 0:00 Uhr Systemzeit hängt nicht am Gerät. Er setzt die Startwerte auf den Gesamtstand, und weil der Gesamtstand nicht fällt, beginnt der neue Tag sauber bei 0. Ob das Gerät kurz vor oder kurz nach Mitternacht zurückspringt, spielt deshalb keine Rolle. Es fehlt nur, was das Gerät zwischen seinem letzten Wert vor dem Zurücksetzen und dem Zurücksetzen selbst gezählt hat.</p><h3 id="wenn-es-schiefgeht" tabindex="-1">Wenn es schiefgeht <a class="header-anchor" href="#wenn-es-schiefgeht" aria-label="Permalink to &quot;Wenn es schiefgeht&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Einstellung</th><th>Was passiert</th><th>Folge</th></tr></thead><tbody><tr><td>Reset-Erkennung aus</td><td>Der Gesamtstand fällt um den Tageswert des Geräts</td><td>Tageswert negativ, Monat und Jahr verlieren den Verbrauch des Vortags</td></tr><tr><td>Schwelle größer als der Tagesverbrauch, z. B. 1 kWh bei 0,6 kWh am Vortag</td><td>Der Rückgang gilt als Messschwankung, neue Werte werden ignoriert, bis sie den alten Stand übersteigen</td><td>Der Anfang des neuen Tages fehlt</td></tr></tbody></table><p>Die passende Einstellung steht unter <a href="./../anleitungen/zaehlerstaende-korrigieren#meter-restarts-after-power-loss">Mein Zähler startet täglich bei 0</a>.</p><p><strong>Ab v0.7.0:</strong> Der Assistent „Quelle hinzufügen&quot; markiert Datenpunkte, deren ID oder Name nach einem Tageswert aussieht, mit „Tageszähler&quot;. Wählst du trotzdem einen, rät er, die Frage „Springt der Wert manchmal auf 0?&quot; mit „Ja&quot; zu beantworten. Das schaltet die Reset-Erkennung ein. Ist sie bei einer Quelle aus, die fällt, meldet der Tab „Probleme&quot; „Zähler springt auf 0, Reset-Erkennung ist aus&quot;.</p><h3 id="besser-ein-zahler-der-nicht-zuruckspringt" tabindex="-1">Besser: ein Zähler, der nicht zurückspringt <a class="header-anchor" href="#besser-ein-zahler-der-nicht-zuruckspringt" aria-label="Permalink to &quot;Besser: ein Zähler, der nicht zurückspringt&quot;">​</a></h3><p>Ein Tageszähler funktioniert, ein Gesamtzähler ist aber genauer. Gibt es keinen, kannst du die Leistung des Geräts als Quelle nehmen oder per Skript einen eigenen, fortlaufend steigenden Datenpunkt schreiben und diesen auswerten.</p><p><strong>Siehe auch:</strong> <a href="#device-reset-detected-mean-reset">Was bedeutet „Device reset detected&quot;?</a> · <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Zähler (kWh) oder Leistung (W)?</a> · <a href="./../anleitungen/quellen-und-einheiten#use-script-datapoints-unreliable-sources">Skript-Datenpunkte für unzuverlässige Quellen</a></p>',38)])])}const b=t(i,[["render",s]]);export{g as __pageData,b as default};
